const defaultSave={tickets:3,owned:{f1:1},pity:0,sound:true,best:0};
let save=loadSave(),run=null,busy=false,filter='all',audioCtx;
function loadSave(){try{return{...defaultSave,...JSON.parse(localStorage.getItem('seongjimon-save')||'{}')}}catch{return{...defaultSave}}}
function persist(){localStorage.setItem('seongjimon-save',JSON.stringify(save));updateHeader()}
function updateHeader(){document.querySelector('#ticket-count').textContent=save.tickets;document.querySelector('#owned-count').textContent=Object.keys(save.owned).length;document.querySelector('#sound-toggle').textContent=save.sound?'♪':'×'}
function grade(m){return GRADES[m.g]}function ability(m){return ABILITIES[m.ability]}function figureClass(m){return`monster-figure shape-${m.shape} grade-${grade(m).id}`}
function show(screen){document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));document.querySelector(`#screen-${screen}`).classList.add('active');document.querySelectorAll('.dock button').forEach(b=>b.classList.toggle('active',b.dataset.go===screen));if(screen==='collection')renderCollection();if(screen==='gacha')renderGacha();if(screen==='dungeons')renderDungeons();tone(260,.05)}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(el.t);el.t=setTimeout(()=>el.classList.remove('show'),1800)}
function tone(freq=300,d=.08,type='sine'){if(!save.sound)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+d);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+d)}catch{}}function wait(ms){return new Promise(r=>setTimeout(r,ms))}
function renderDungeons(){document.querySelector('#dungeon-grid').innerHTML=DUNGEONS.map(d=>`<button class="dungeon-card" style="--dungeon-color:${d.color}" data-dungeon="${d.id}"><span class="difficulty">${d.difficulty}</span><h3>${d.name}</h3><p>${d.desc}</p><div class="dungeon-meta"><span>${d.floors}구역</span><span>완주 🎟 ${d.bonus}</span><span>${GRADES[d.maxG].label}까지</span></div></button>`).join('')}
function freshState(m){return{...m,atk:1,def:1,acc:0,dot:0,dotTurns:0,stun:0,shield:0,traitUsed:false,lastMove:null}}
function startRun(dungeonId){const dungeon=DUNGEONS.find(d=>d.id===dungeonId)||DUNGEONS[0],owned=MONSTERS.filter(m=>save.owned[m.id]),base=[...owned].sort((a,b)=>b.g-a.g)[0]||MONSTERS[0],maxHp=92+base.g*14;run={dungeon,floor:1,wins:0,tickets:0,boost:0,player:{...freshState(base),level:1,maxHp,hp:maxHp},enemy:null};show('battle');nextBattle()}
function pickEnemy(){const d=run.dungeon;if(run.floor===d.floors){const bosses=MONSTERS.filter(m=>m.g===d.maxG);return bosses[Math.floor(Math.random()*bosses.length)]}const progress=run.floor/d.floors,ceiling=Math.min(d.maxG,d.minG+Math.floor(progress*(d.maxG-d.minG+1))),pool=MONSTERS.filter(m=>m.g>=d.minG&&m.g<=ceiling);return pool[Math.floor(Math.random()*pool.length)]}
function nextBattle(){busy=false;const base=pickEnemy(),level=run.floor+Math.max(0,base.g-1),hp=Math.round((58+level*15+base.g*10)*run.dungeon.scale);run.enemy={...freshState(base),level,maxHp:hp,hp};run.player.level=Math.max(1,Math.ceil(run.floor/2));run.player.traitUsed=false;renderBattle();log(`${run.dungeon.name} ${run.floor}구역. ${ability(run.enemy).name} 특성의 지냄이 나타났다.`)}
function renderBattle(){setCombatant('player',run.player);setCombatant('enemy',run.enemy);document.querySelector('#floor-label').textContent=`${run.dungeon.name} · ${run.floor}/${run.dungeon.floors}구역`;document.querySelector('#run-tickets').textContent=run.tickets;const pips=document.querySelector('#floor-pips');pips.innerHTML='';for(let i=1;i<=run.dungeon.floors;i++){const x=document.createElement('i');if(i<run.floor)x.className='done';if(i===run.floor)x.className='current';pips.append(x)}renderMoves()}
function setCombatant(side,m){document.querySelector(`#${side}-grade`).textContent=grade(m).label.toUpperCase();document.querySelector(`#${side}-name`).textContent=m.name;document.querySelector(`#${side}-ability`).textContent=`특성 · ${ability(m).name} — ${ability(m).desc}`;document.querySelector(`#${side}-level`).textContent=`Lv.${m.level||1}`;const fig=document.querySelector(`#${side}-figure`);fig.className=figureClass(m);fig.innerHTML='<span class="face-dot left"></span><span class="face-dot right"></span>';setHp(side,m);renderStatus(side,m)}
function setHp(side,m){const pct=Math.max(0,m.hp/m.maxHp*100),bar=document.querySelector(`#${side}-hp`);bar.style.width=`${pct}%`;bar.style.background=pct<25?'#ff5468':pct<55?'#ffd15c':'#c6ff4a';document.querySelector(`#${side}-hp-text`).textContent=`${Math.max(0,Math.round(m.hp))} / ${m.maxHp}`}
function renderStatus(side,m){const tags=[];if(m.atk>1)tags.push(['공격↑','good']);if(m.atk<1)tags.push(['공격↓','bad']);if(m.def<1)tags.push(['방어↓','bad']);if(m.acc<0)tags.push(['명중↓','bad']);if(m.shield>0)tags.push([`보호막 ${Math.round(m.shield)}`,'good']);if(m.dotTurns>0)tags.push([`잔향침식 ${m.dotTurns}턴`,'bad']);if(m.stun>0)tags.push(['행동 봉쇄','bad']);document.querySelector(`#${side}-status`).innerHTML=tags.map(t=>`<span class="${t[1]}">${t[0]}</span>`).join('')}
function movesFor(m){const set=[...MOVE_SETS[m.g]];if(m.variant===4)set[0]='pierce';if(m.variant===5)set[1]=m.g>2?'dimension':'compress';return set.map(id=>({id,...MOVES[id]}))}
function renderMoves(){const grid=document.querySelector('#move-grid');grid.innerHTML='';movesFor(run.player).forEach((m,i)=>{const b=document.createElement('button');b.className='move-button';b.innerHTML=`<span><strong>${m.name}</strong><small>${m.desc}</small></span><b>${m.power?`위력 ${m.power}`:'변화기'}<br>${m.tag}</b>`;b.onclick=()=>playerMove(m,i);grid.append(b)})}
function log(t){document.querySelector('#battle-log').textContent=t}function animate(side,cls){const f=document.querySelector(`#${side}-figure`);f.classList.remove(cls);void f.offsetWidth;f.classList.add(cls);setTimeout(()=>f.classList.remove(cls),450)}
function heal(actor,amount){const before=actor.hp;actor.hp=Math.min(actor.maxHp,actor.hp+Math.round(amount));return Math.round(actor.hp-before)}
function beginTurn(actor,side){const notes=[];if(actor.ability==='renewal'){const h=heal(actor,actor.maxHp*.03);if(h)notes.push(`${ability(actor).name}으로 ${h} 회복`)}if(actor.dotTurns>0){actor.hp-=actor.dot;actor.dotTurns--;notes.push(`잔향침식 ${actor.dot} 피해`)}setHp(side,actor);renderStatus(side,actor);return notes}
function damageCalc(attacker,target,move){let mult=attacker.atk*(attacker===run.player?1+run.boost/100:1);if(attacker.ability==='diffuse')mult*=1.1;if(attacker.ability==='resonance'&&attacker.lastMove===move.id)mult*=1.25;if(attacker.ability==='surge'&&attacker.hp/attacker.maxHp<=.35)mult*=1.3;if(attacker.ability==='sovereignty')mult*=1.08;let defense=move.pierce?1:target.def;if(target.ability==='armor')defense*=1.08;if(target.ability==='sovereignty')defense*=1.08;const critChance=.08+(attacker.ability==='critical'?.22:0)+(move.crit||0)/100,crit=Math.random()<critChance;let dmg=Math.max(3,Math.round(move.power*mult/defense*(.84+Math.random()*.28)*(crit?1.55:1)));if(target.ability==='veil'&&!target.traitUsed){dmg=Math.round(dmg*.65);target.traitUsed=true}const blocked=Math.min(target.shield,dmg);target.shield-=blocked;dmg-=blocked;target.hp-=dmg;return{dmg,blocked,crit}}
function applyEffect(attacker,target,move){if(!move.effect)return'';const chance=Math.min(100,(move.chance||100)+(attacker.ability==='conductor'?20:0));if(Math.random()*100>chance)return' 부가효과는 발동하지 않았다.';switch(move.effect){case'accuracy':target.acc=Math.max(-30,target.acc-12);return' 상대의 명중률이 내려갔다.';case'shield':attacker.shield+=22+attacker.g*4;return' 보호막이 생성됐다.';case'rest':{const h=heal(attacker,attacker.maxHp*.35);attacker.def=Math.max(.68,attacker.def*.82);return` ${h} 회복했지만 방어가 내려갔다.`}case'attackDown':target.atk=Math.max(.65,target.atk*.84);return' 상대의 공격이 내려갔다.';case'healShield':{const h=heal(attacker,attacker.maxHp*.22);attacker.shield+=18+attacker.g*3;return` ${h} 회복하고 보호막을 생성했다.`}case'attackUp':attacker.atk=Math.min(1.65,attacker.atk*1.15);return' 자신의 공격이 올랐다.';case'defenseDown':target.def=Math.max(.58,target.def*.78);return' 상대의 방어가 크게 내려갔다.';case'dot':target.dot=7+attacker.g*2;target.dotTurns=3;return' 상대가 3턴간 잔향침식 상태가 됐다.';case'stun':target.stun=1;return' 상대의 다음 행동을 봉쇄했다.';case'dispel':target.shield=0;target.atk=Math.min(1,target.atk);target.def=Math.min(1,target.def);return' 상대의 보호막과 강화를 제거했다.';default:return''}}
function useMove(attacker,target,move,aSide,tSide){const dodge=target.ability==='phase'?15:0,hitChance=Math.max(35,move.acc+attacker.acc-dodge);if(Math.random()*100>hitChance){if(attacker.ability==='reflux'){const h=heal(attacker,attacker.maxHp*.08);setHp(aSide,attacker);return`${move.name}은 빗나갔다. ${ability(attacker).name}으로 ${h} 회복했다.`}return`${move.name}은 빗나갔다.`}let text=`${move.name}!`;if(move.power){const r=damageCalc(attacker,target,move);text+=` ${r.dmg} 피해${r.crit?' · 치명타!':''}${r.blocked?` · 보호막 ${r.blocked} 흡수`:''}.`;if(move.drain){const h=heal(attacker,r.dmg*move.drain);text+=` ${h} 흡수.`}if(attacker.ability==='absorb'){const h=heal(attacker,r.dmg*.15);if(h)text+=` ${ability(attacker).name}으로 ${h} 회복.`}}text+=applyEffect(attacker,target,move);if(move.recoil){const recoil=Math.max(1,Math.round(attacker.maxHp*move.recoil));attacker.hp-=recoil;text+=` 반동 ${recoil} 피해.`}attacker.lastMove=move.id;setHp(aSide,attacker);setHp(tSide,target);renderStatus(aSide,attacker);renderStatus(tSide,target);return text}
async function playerMove(move,idx){if(busy)return;busy=true;document.querySelectorAll('.move-button').forEach(b=>b.disabled=true);const start=beginTurn(run.player,'player');if(run.player.hp<=0){gameOver();return}if(run.player.stun>0){run.player.stun--;log(`행동이 봉쇄됐다. ${start.join(' · ')}`);await wait(700);enemyTurn();return}animate('player','attack');tone(330+idx*70,.12,'sawtooth');await wait(260);const text=useMove(run.player,run.enemy,move,'player','enemy');animate('enemy','hit');log(start.length?`${start.join(' · ')}. ${text}`:text);await wait(720);if(run.enemy.hp<=0){winBattle();return}if(run.player.hp<=0){gameOver();return}enemyTurn()}
async function enemyTurn(){const start=beginTurn(run.enemy,'enemy');if(run.enemy.hp<=0){winBattle();return}if(run.enemy.stun>0){run.enemy.stun--;log(`${run.enemy.name}의 행동이 봉쇄됐다. ${start.join(' · ')}`);await wait(650);busy=false;document.querySelectorAll('.move-button').forEach(b=>b.disabled=false);return}const moves=movesFor(run.enemy),move=moves[Math.floor(Math.random()*moves.length)];animate('enemy','attack');tone(150,.14,'square');await wait(280);const text=useMove(run.enemy,run.player,move,'enemy','player');animate('player','hit');log(start.length?`${start.join(' · ')}. ${text}`:text);await wait(720);if(run.player.hp<=0){gameOver();return}if(run.enemy.hp<=0){winBattle();return}busy=false;document.querySelectorAll('.move-button').forEach(b=>b.disabled=false)}
function winBattle(){run.wins++;const got=Math.random()<run.dungeon.ticket?1:0;run.tickets+=got;log(`${run.enemy.name} 격파!${got?' 뽑기 티켓을 발견했다.':''}`);tone(520,.12);setTimeout(()=>{if(run.floor>=run.dungeon.floors){run.tickets+=run.dungeon.bonus;completeRun()}else showRewards()},850)}
function showRewards(){document.querySelector('#reward-overlay').classList.add('active');const choices=[['✚','잔향 회복','체력 35% 회복','heal'],['⬆','농도 강화','이번 원정 공격력 +6%','power'],['🎟','균열 티켓','뽑기 티켓 +1','ticket']].sort(()=>Math.random()-.5);document.querySelector('#reward-options').innerHTML=choices.map(c=>`<button class="reward-option" data-reward="${c[3]}"><b>${c[0]}</b><strong>${c[1]}</strong><small>${c[2]}</small></button>`).join('')}
function takeReward(type){if(type==='heal')heal(run.player,run.player.maxHp*.35);if(type==='power')run.boost+=6;if(type==='ticket')run.tickets++;document.querySelector('#reward-overlay').classList.remove('active');run.floor++;nextBattle()}
function completeRun(){save.tickets+=run.tickets;save.best=Math.max(save.best,run.dungeon.floors);persist();document.querySelector('#result-floor').textContent=`${run.dungeon.name} 완주`;finishResult()}function gameOver(){save.tickets+=run.tickets;save.best=Math.max(save.best,run.floor);persist();document.querySelector('#result-floor').textContent=`${run.dungeon.name} ${run.floor}구역`;finishResult()}function finishResult(){document.querySelector('#result-wins').textContent=run.wins;document.querySelector('#result-tickets').textContent=run.tickets;show('gameover')}function abandon(){if(!run)return;save.tickets+=run.tickets;persist();show('lobby');toast('원정을 종료하고 획득 티켓을 보관했다.')}
function rollGrade(){if(save.pity>=29)return 4+Math.floor(Math.random()*2);let r=Math.random()*100,sum=0;for(let i=0;i<GRADES.length;i++){sum+=GRADES[i].odds;if(r<sum)return i}return 0}
function pull(){if(save.tickets<1){toast('티켓이 부족하다. 던전에서 획득할 수 있다.');tone(110,.1);return}save.tickets--;const gi=rollGrade();save.pity=gi>=4?0:save.pity+1;const pool=MONSTERS.filter(m=>m.g===gi),m=pool[Math.floor(Math.random()*pool.length)],isNew=!save.owned[m.id];save.owned[m.id]=(save.owned[m.id]||0)+1;persist();renderGacha();summonReveal(m,isNew)}
function summonReveal(m,isNew){const o=document.querySelector('#summon-overlay'),g=grade(m);o.className=`summon-overlay active reveal-${g.id}`;document.querySelector('#summon-result-grade').textContent=`${g.label.toUpperCase()} · 특성 ${ability(m).name}`;document.querySelector('#summon-result-grade').style.color=g.color;const f=document.querySelector('#summon-result-figure');f.className=figureClass(m);f.innerHTML='<span class="face-dot left"></span><span class="face-dot right"></span>';document.querySelector('#summon-result-name').textContent=m.name;document.querySelector('#summon-new').textContent=isNew?'NEW!':`보유 ${save.owned[m.id]}개`;tone(260+m.g*105,.35,'sawtooth')}
function renderGacha(){document.querySelector('#odds-list').innerHTML=GRADES.map(g=>`<span style="border-color:${g.color}55;color:${g.color}">${g.label} ${g.odds}%</span>`).join('');document.querySelector('#pity-text').textContent=`Smell 이상 확정까지 ${30-save.pity}회`;document.querySelector('#pull-once').disabled=save.tickets<1}
function renderCollection(){const fs=document.querySelector('#grade-filters');fs.innerHTML='';[['all','전체'],...GRADES.map(g=>[g.id,g.label])].forEach(([id,label])=>{const b=document.createElement('button');b.textContent=label;b.classList.toggle('active',filter===id);b.onclick=()=>{filter=id;renderCollection()};fs.append(b)});const list=filter==='all'?MONSTERS:MONSTERS.filter(m=>grade(m).id===filter);document.querySelector('#collection-grid').innerHTML=list.map(m=>{const owned=save.owned[m.id]||0;return`<article class="collection-card ${owned?'':'locked'}"><small>${owned?`×${owned}`:'???'}</small><span style="color:${grade(m).color}">${grade(m).label.toUpperCase()} · ${m.form}</span><div class="${figureClass(m)}">${owned?'<i class="face-dot left"></i><i class="face-dot right"></i>':''}</div><h3>${owned?m.name:'아직 관측되지 않은 지냄'}</h3>${owned?`<span class="trait">특성 · ${ability(m).name}<br>${ability(m).desc}</span>`:''}</article>`}).join('')}
document.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go)show(go.dataset.go);const dungeon=e.target.closest('[data-dungeon]');if(dungeon)startRun(dungeon.dataset.dungeon);const reward=e.target.closest('[data-reward]');if(reward)takeReward(reward.dataset.reward)});
document.querySelector('#start-run').onclick=()=>show('dungeons');document.querySelector('#retry-run').onclick=()=>show('dungeons');document.querySelector('#abandon-run').onclick=abandon;document.querySelector('#pull-once').onclick=pull;document.querySelector('#summon-close').onclick=()=>document.querySelector('#summon-overlay').classList.remove('active');document.querySelector('#sound-toggle').onclick=()=>{save.sound=!save.sound;persist();toast(save.sound?'소리를 켰다.':'소리를 껐다.')};
updateHeader();renderGacha();renderDungeons();
window.seongjimon={openDungeons:()=>show('dungeons'),startDungeon:startRun,openGacha:()=>show('gacha'),openCollection:()=>show('collection'),getStatus:()=>({tickets:save.tickets,owned:Object.keys(save.owned).length,total:MONSTERS.length,bestFloor:save.best,inRun:!!run,dungeon:run?.dungeon.name||null})};
if(document.modelContext?.registerTool){const tools=[{name:'read_game_status',title:'게임 상태 확인',description:'보유 티켓, 도감 수집 수, 최고 도달 구역과 원정 진행 여부를 확인한다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>window.seongjimon.getStatus()},{name:'open_dungeon_selection',title:'던전 선택 열기',description:'난이도별 던전을 고를 수 있는 화면을 연다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{show('dungeons');return{opened:true,dungeons:DUNGEONS.map(d=>d.name)}}},{name:'open_jinaem_collection',title:'지냄 도감 열기',description:'수집한 지냄과 각 특성을 확인하는 도감 화면을 연다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{show('collection');return{opened:true,owned:Object.keys(save.owned).length,total:MONSTERS.length}}}];tools.forEach(tool=>{try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}})}
